    # --- Securing rows: 2 passes to anchor the yarn before releasing the hook ---
    in Leftward direction:
        knit Front_Needles[0:width];
    in Rightward direction:
        knit Front_Needles[0:width];

    releasehook;

    # --- Stockinette body: 6 rows, alternating carriage direction each pass ---
    for row in range(height):
        in reverse direction:
            knit Loops;

